/**
 * Modal side sheet (`design/components/drawer.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/drawer.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/dialog'

import {
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  agentMember,
  cell,
  derived,
  elementRef,
  focusPlace,
  focusReturnTarget,
  mergeParts,
  modalFocusTarget,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/drawer.module.css'
import { Button, type ButtonProps } from '../controls/Button'

export type DrawerSide = NonNullable<DrawerProps['side']>

/** Modal side sheet: the inputs it takes, by the React member's prop names. */
export interface DrawerProps {
  /**
   * The ✕'s accessible name, as in Dialog; localized hosts replace the default `Close`.
   */
  closeLabel?: string
  defaultOpen?: boolean
  description?: string
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  dismissible?: boolean
  /**
   * The same as Dialog's, from the shared focus code: unset focuses the first tabbable per the
   * focus-order rule, and `dismiss` suits a panel asking whether you meant it.
   */
  initialFocus?: 'primary' | 'dismiss'
  open?: boolean
  side?: 'start' | 'end' | 'bottom'
  /**
   * Inline size for a start/end sheet, block size for a bottom one. Both derive from the space
   * scale, so a roomier theme gets a larger sheet.
   */
  size?: 'sm' | 'md' | 'lg'
  title: string
}

/** Modal side sheet. */
@Component({
  selector: 'pm-drawer',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Portal, Ref, SlotOutlet, SlotTemplate, Spread, Button],
  // prettier-ignore
  template: `<ng-template pmSlot="footer" [pmSlotOf]="$"><ng-content select="[slot=footer]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<ng-template pmPortal>@if (e1()) {<!-- scrim -->
<div
[pmSpread]="e2()"
[pmRef]="scrim"
></div>}
@if (e3()) {<!-- positioner -->
<div
[pmSpread]="e4()"
><!-- panel -->
<div
[pmSpread]="e5()"
[pmRef]="panel"
><!-- header -->
<div
[attr.class]="e6()"
><!-- heading -->
<div
[attr.class]="e7()"
><!-- title -->
<h2
[pmSpread]="e8()"
>{{ e9() }}</h2>
@if (e10()) {<!-- description -->
<p
[pmSpread]="e11()"
>{{ e12() }}</p>}</div>
@if (e13()) {<!-- close -->
<div
[attr.class]="e14()"
data-dialog-part="close"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e15()"
icon="close"
[label]="e16()"
(click)="h1()"
></pm-button></div>}</div>
<!-- body -->
<div
[attr.class]="e17()"
data-dialog-part="body"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>
@if (e18()) {<!-- footer -->
<div
[attr.class]="e19()"
data-dialog-part="footer"
><ng-container [pmSlotOutlet]="'footer'" [pmSlotOf]="$" /></div>}</div></div>}</ng-template>`,
})
export class Drawer {
  /**
   * The ✕'s accessible name, as in Dialog; localized hosts replace the default `Close`.
   */
  readonly closeLabel = input<
    Exclude<DrawerProps['closeLabel'], undefined>,
    DrawerProps['closeLabel']
  >('Close', {
    transform: (value: DrawerProps['closeLabel']) => (value === undefined ? 'Close' : value),
  })
  readonly defaultOpen = input<DrawerProps['defaultOpen']>(undefined)
  readonly description = input<DrawerProps['description']>(undefined)
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  readonly dismissible = input<
    Exclude<DrawerProps['dismissible'], undefined>,
    DrawerProps['dismissible']
  >(true, {
    transform: (value: DrawerProps['dismissible']) => (value === undefined ? true : value),
  })
  /**
   * The same as Dialog's, from the shared focus code: unset focuses the first tabbable per the
   * focus-order rule, and `dismiss` suits a panel asking whether you meant it.
   */
  readonly initialFocus = input<
    Exclude<DrawerProps['initialFocus'], undefined>,
    DrawerProps['initialFocus']
  >('primary', {
    transform: (value: DrawerProps['initialFocus']) => (value === undefined ? 'primary' : value),
  })
  readonly open = input<DrawerProps['open']>(undefined)
  readonly side = input<Exclude<DrawerProps['side'], undefined>, DrawerProps['side']>('end', {
    transform: (value: DrawerProps['side']) => (value === undefined ? 'end' : value),
  })
  /**
   * Inline size for a start/end sheet, block size for a bottom one. Both derive from the space
   * scale, so a roomier theme gets a larger sheet.
   */
  readonly size = input<Exclude<DrawerProps['size'], undefined>, DrawerProps['size']>('md', {
    transform: (value: DrawerProps['size']) => (value === undefined ? 'md' : value),
  })
  readonly title = input.required<DrawerProps['title']>()
  readonly onOpenChange = output<boolean>({ alias: 'openChange' })
  protected readonly $ = useMember({
    events: ['openChange'],
    props: {
      closeLabel: () => this.closeLabel(),
      defaultOpen: () => this.defaultOpen(),
      description: () => this.description(),
      dismissible: () => this.dismissible(),
      initialFocus: () => this.initialFocus(),
      open: () => this.open(),
      side: () => this.side(),
      size: () => this.size(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly returnTo = cell(() => null as ReturnType<typeof focusPlace>)
  protected readonly panel = elementRef<HTMLElement>()
  protected readonly scrim = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          open: this.$p.open,
          defaultOpen: this.$p.defaultOpen,
          closeOnEscape: this.$p.dismissible,
          closeOnInteractOutside: this.$p.dismissible,
          initialFocusEl: () => modalFocusTarget(this.panel.value, this.$p.initialFocus),
          finalFocusEl: () => focusReturnTarget(this.returnTo.value, [this.panel.value]),
          onOpenChange: (details) => {
            this.$.emit(this.onOpenChange, 'onOpenChange', details.open)
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly scrimPresent = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.scrim.value,
      'dialog.scrim',
    ),
  )
  protected readonly panelPresent = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.panel.value,
      'drawer.panel',
      () => ({ sheetSide: this.$p.side }),
    ),
  )
  private release2: (() => void) | undefined

  constructor() {
    watchEffect(
      () => this.api.value.open,
      () => this.effect1(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return this.scrimPresent.value()
  }

  protected e2() {
    if (!this.scrimPresent.value()) return undefined as never
    return mergeParts(this.api.value.getBackdropProps(), { class: styles.scrim, hidden: undefined })
  }

  protected e3() {
    return this.panelPresent.value()
  }

  protected e4() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps(), {
      class: styles.positioner,
      'data-side': this.$p.side,
    })
  }

  protected e5() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.panel,
      hidden: undefined,
      'data-side': this.$p.side,
      'data-size': this.$p.size,
      'data-member': 'drawer',
    })
  }

  protected e6() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.header
  }

  protected e7() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.heading
  }

  protected e8() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getTitleProps(), { class: styles.title })
  }

  protected e9() {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.title
  }

  protected e10() {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.description !== undefined
  }

  protected e11() {
    if (!this.panelPresent.value()) return undefined as never
    if (!(this.$p.description !== undefined)) return undefined as never
    return mergeParts(this.api.value.getDescriptionProps(), { class: styles.description })
  }

  protected e12() {
    if (!this.panelPresent.value()) return undefined as never
    if (!(this.$p.description !== undefined)) return undefined as never
    return this.$p.description
  }

  protected e13() {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.dismissible
  }

  protected e14() {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.$p.dismissible) return undefined as never
    return styles.close
  }

  protected e15(): ButtonProps['iconOnly'] {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.$p.dismissible) return undefined as never
    return true
  }

  protected e16(): ButtonProps['label'] {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.$p.dismissible) return undefined as never
    return this.$p.closeLabel
  }

  protected h1(): void {
    if (!this.panelPresent.value()) return
    if (!this.$p.dismissible) return
    this.api.value.setOpen(false)
  }

  protected e17() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.body
  }

  protected e18() {
    if (!this.panelPresent.value()) return undefined as never
    return this.$.filled('footer')
  }

  protected e19() {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.$.filled('footer')) return undefined as never
    return styles.footer
  }

  private effect1(): void {
    void (this.api.value.open && (this.returnTo.value = focusPlace(document.activeElement)))
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'Drawer',
      element: () => this.panel.value,
      state: () => ({ open: this.api.value.open }),
      actions: {
        close: () =>
          (() => {
            if (!this.$p.dismissible)
              throw new Error('The drawer asks for a choice among its own actions.')
            if (this.api.value.open) this.api.value.setOpen(false)
          })(),
      },
    })
    this.release2 = () => {
      ran()
    }
  }
}
